def flatten(target, **kwargs):
    levels = kwargs.pop('levels', 1)
    init = kwargs.pop('init', list)
    spec = kwargs.pop('spec', T)

    if kwargs:
        raise TypeError('unexpected keyword args: %r' % sorted(kwargs.keys()))

    if levels < 0:
        raise ValueError('levels must be >= 0')

    if levels == 0:
        return target

    try:
        # Check if target is iterable
        iter(target)
    except TypeError:
        raise FoldError('can only flatten iterable targets, not %s type' %
                        type(target).__name__)

    # Apply spec if provided
    if spec is not T:
        target = glom(target, spec)

    # Base case: levels == 1
    if levels == 1:
        if init == str:
            # Special handling for string concatenation
            result = ''
            for item in target:
                if hasattr(item, '__iter__') and not isinstance(item, (str, bytes)):
                    # If item is iterable but not a string, flatten it recursively
                    result += ''.join(str(x) for x in flatten(item, levels=1, init=str))
                else:
                    result += str(item)
            return result
        else:
            # Regular list-like flattening
            result = init()
            for item in target:
                try:
                    iter(item)
                    # If item is iterable, extend with flattened version
                    if hasattr(item, '__iter__') and not isinstance(item, (str, bytes)):
                        result.extend(flatten(item, levels=1, init=init))
                    else:
                        result.append(item)
                except TypeError:
                    # Not iterable, just append
                    result.append(item)
            return result
    else:
        # Recursive case for levels > 1
        flattened = []
        for item in target:
            try:
                iter(item)
                flattened.extend(flatten(item, levels=levels-1, init=init))
            except TypeError:
                flattened.append(item)
        return init(flattened) if init != list else flattened
